#!/usr/bin/env bash
# Rotates the application API token in Secrets Manager.
#   scripts/rotate-app-token.sh <name-prefix>      e.g. sci-dev
# The new value is generated by Secrets Manager, written through a 0600 temp
# file (never a command-line argument, so it is not visible in `ps`), and the
# old value automatically becomes AWSPREVIOUS - which the application keeps
# accepting until the next rotation, giving clients a grace period.
set -euo pipefail
NAME="${1:?usage: $0 <name-prefix>}"
SECRET_ID="${NAME}/app/api-token"
umask 077
tmp="$(mktemp)"
trap 'rm -f "${tmp}"' EXIT
aws secretsmanager get-random-password --password-length 48 --exclude-punctuation \
  --query RandomPassword --output text >"${tmp}"
aws secretsmanager put-secret-value --secret-id "${SECRET_ID}" --secret-string "file://${tmp}" \
  --query '{Secret:Name,Version:VersionId}' --output table
echo "rotated ${SECRET_ID}; previous token stays valid until the next rotation"
